INSERT INTO system_role(name,code,sort,status,type,data_scope,data_scope_dept_ids,remark,tenant_id) SELECT '超级管理员','super_admin',0,0,1,1,'[]','芋道原生管理员',1 WHERE NOT EXISTS(SELECT 1 FROM system_role WHERE tenant_id=1 AND code='super_admin' AND deleted=0);
INSERT INTO system_role_menu(role_id,menu_id,tenant_id) SELECT r.id,m.id,1 FROM system_role r JOIN system_menu m ON m.deleted=0 AND m.status=0 WHERE r.code='super_admin' AND r.tenant_id=1 AND r.deleted=0 AND NOT EXISTS(SELECT 1 FROM system_role_menu rm WHERE rm.role_id=r.id AND rm.menu_id=m.id AND rm.tenant_id=1 AND rm.deleted=0);
